from pathlib import Path

path = Path('/home/ubuntu/split/frontend/src/App.tsx')
source = path.read_text()
start = source.index('function ExpenseModal')
end = source.index('function CommandPalette', start)
replacement = r'''function ExpenseModal({ onClose, onSave }: { onClose: () => void; onSave: (expense: Expense) => void }) {
  const [title, setTitle] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("Food");
  const [mode, setMode] = useState("Equal");
  const [payer, setPayer] = useState("Rafi");
  const [note, setNote] = useState("");
  const [receiptAttached, setReceiptAttached] = useState(false);
  const [participants, setParticipants] = useState(["Rafi", "Tisha", "Nabil", "Mahi"]);
  const parsedAmount = Number(amount) || 0;
  const perPerson = parsedAmount / Math.max(participants.length, 1);
  const canSave = title.trim().length > 1 && parsedAmount > 0 && participants.length > 0;
  const categories = [
    { name: "Food", icon: "◒", hint: "Meals, coffee, snacks" },
    { name: "Stay", icon: "⌂", hint: "Hotels and rentals" },
    { name: "Transport", icon: "↗", hint: "Rides and tickets" },
    { name: "Activities", icon: "✦", hint: "Plans and experiences" },
  ];
  const people = ["Rafi", "Tisha", "Nabil", "Mahi", "Shuvo"];
  const toggleParticipant = (name: string) => setParticipants((current) => current.includes(name) ? current.filter((item) => item !== name) : [...current, name]);
  return <div className="modal-backdrop expense-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><form className="expense-modal expense-modal-modern" onSubmit={(event) => { event.preventDefault(); if (!canSave) return; onSave({ id: crypto.randomUUID(), title: title.trim(), category, amount: parsedAmount, payer, date: "Just now", note: note.trim() || (mode === "Equal" ? "Split equally with the group" : `${mode} split`), receipt: receiptAttached, status: "Confirmed" }); }}><div className="expense-modal-head"><div className="expense-kicker"><span className="expense-kicker-dot" /> NEW SHARED EXPENSE</div><button type="button" className="modal-close-button" onClick={onClose} aria-label="Close expense modal"><X size={18} /></button><h2>Make the split feel easy.</h2><p>Add one expense and we’ll keep the group balance clear.</p></div><div className="expense-modal-body"><div className="expense-form-column"><label className="expense-field expense-title-field"><span>What did you pay for?</span><div className="expense-input-shell"><Receipt size={17} /><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="e.g. Dinner at Dhanmondi" /></div></label><div className="expense-two-col"><label className="expense-field"><span>Amount</span><div className="expense-input-shell amount-shell"><b>৳</b><input value={amount} onChange={(event) => setAmount(event.target.value.replace(/[^0-9.]/g, ""))} inputMode="decimal" placeholder="0.00" /></div></label><label className="expense-field"><span>Paid by</span><div className="expense-select-shell"><Avatar member={members.find((member) => member.name === payer) || members[0]} size="sm" /><select value={payer} onChange={(event) => setPayer(event.target.value)}>{people.map((person) => <option key={person}>{person}</option>)}</select><ChevronDown size={14} /></div></label></div><div className="expense-section-label"><span>Choose a category</span><small>Helps your group understand the spend</small></div><div className="expense-category-grid">{categories.map((item) => <button type="button" key={item.name} className={`expense-category-choice ${category === item.name ? "selected" : ""}`} onClick={() => setCategory(item.name)}><span>{item.icon}</span><strong>{item.name}</strong><small>{item.hint}</small></button>)}</div><div className="expense-section-label"><span>Who is included?</span><small>{participants.length} of {people.length} people selected</small></div><div className="participant-picker">{people.map((person) => { const member = members.find((item) => item.name === person) || members[0]; const selected = participants.includes(person); return <button type="button" key={person} className={`participant-chip ${selected ? "selected" : ""}`} onClick={() => toggleParticipant(person)}><Avatar member={member} size="sm" /><span>{person}</span>{selected ? <Check size={13} /> : <Plus size={13} />}</button>; })}</div><div className="expense-section-label split-label"><span>How should this split?</span><small>Change this later if the group decides differently</small></div><div className="split-mode-grid">{[{ name: "Equal", icon: <Users size={16} />, copy: "Everyone pays the same" }, { name: "Exact", icon: <WalletCards size={16} />, copy: "Set each person’s amount" }, { name: "Percentage", icon: <ChartNoAxesColumnIncreasing size={16} />, copy: "Split by contribution" }].map((item) => <button type="button" key={item.name} className={`split-mode-choice ${mode === item.name ? "selected" : ""}`} onClick={() => setMode(item.name)}>{item.icon}<span><strong>{item.name}</strong><small>{item.copy}</small></span>{mode === item.name && <Check size={14} />}</button>)}</div><label className="expense-field expense-note-field"><span>Note <em>Optional</em></span><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add a little context for the group…" rows={2} /></label><button type="button" className={`receipt-upload ${receiptAttached ? "attached" : ""}`} onClick={() => setReceiptAttached((value) => !value)}><span className="receipt-upload-icon">{receiptAttached ? <Check size={16} /> : <Paperclip size={16} />}</span><span><strong>{receiptAttached ? "Receipt attached" : "Attach a receipt"}</strong><small>{receiptAttached ? "Ready to keep the expense trustworthy" : "Optional · JPG, PNG or PDF"}</small></span><ArrowUpRight size={15} /></button></div><aside className="expense-preview-panel"><div className="preview-eyebrow">LIVE SPLIT PREVIEW</div><div className="preview-orb"><Sparkles size={18} /></div><h3>{title.trim() || "Your new expense"}</h3><p>{category} · paid by {payer}</p><div className="preview-total"><small>Total</small><strong>{money(parsedAmount)}</strong></div><div className="preview-divider" /><div className="preview-split-row"><span><Users size={15} /> {participants.length} people</span><strong>{money(perPerson)} each</strong></div><div className="preview-members">{participants.slice(0, 4).map((person) => <Avatar key={person} member={members.find((member) => member.name === person) || members[0]} size="sm" />)}{participants.length > 4 && <span className="preview-more">+{participants.length - 4}</span>}</div><div className="preview-tip"><Sparkles size={14} /><span>Everyone sees the same story, from payment to settlement.</span></div></aside></div><div className="expense-modal-footer"><button type="button" className="modal-cancel" onClick={onClose}>Cancel</button><button className="expense-save-button" type="submit" disabled={!canSave}><span>{canSave ? "Save expense" : "Add a title and amount"}</span><ArrowUpRight size={16} /></button></div></form></div>;
}
'''
path.write_text(source[:start] + replacement + source[end:])
